//! `database.db` format parity with upstream zigbee-herdsman (2026-11-19).
//!
//! The fixture is generated by `tools/oracle/db-fixture.mjs` with the pinned
//! upstream `Database` writer, so its bytes are canonical Node output.

use std::path::{Path, PathBuf};
use std::sync::{Arc, Mutex};

use serde_json::{json, Value};

use zigbee_apiarist::controller::database::Database;
use zigbee_apiarist::controller::model::device::Device;
use zigbee_apiarist::controller::model::entity::inject_database;
use zigbee_apiarist::controller::model::group::Group;

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join("database-node.golden")
}

fn temp_dir(tag: &str) -> PathBuf {
    let dir = std::env::temp_dir().join(format!(
        "z2m-db-roundtrip-{tag}-{}-{}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    std::fs::create_dir_all(&dir).unwrap();
    dir
}

fn entries() -> Vec<Value> {
    std::fs::read_to_string(fixture())
        .unwrap()
        .split('\n')
        .filter(|line| !line.is_empty())
        .map(|line| serde_json::from_str(line).unwrap())
        .collect()
}

#[test]
fn open_and_write_preserve_the_node_database_bytes() {
    let dir = temp_dir("raw");
    let path = dir.join("database.db");
    std::fs::copy(fixture(), &path).unwrap();

    let database = Database::open(&path);
    database.write().unwrap();

    assert_eq!(
        std::fs::read(&path).unwrap(),
        std::fs::read(fixture()).unwrap(),
        "Database::open -> write must be byte-identical to the Node writer"
    );
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
fn device_entries_roundtrip_through_the_model() {
    Device::reset_cache();
    Group::reset_cache();

    for entry in entries() {
        if entry.get("type").and_then(Value::as_str) == Some("Group") {
            continue;
        }
        let device = Device::from_database_entry(&entry);
        let actual = device.test_database_entry();
        assert_eq!(
            actual, entry,
            "device {} ({}) model serialization differs",
            entry["ieeeAddr"], entry["id"]
        );
        assert_eq!(
            serde_json::to_string(&actual).unwrap(),
            serde_json::to_string(&entry).unwrap(),
            "device {} ({}) model serialization differs at the JSON byte level",
            entry["ieeeAddr"],
            entry["id"]
        );
    }
}

#[test]
fn binds_and_reportings_keep_the_upstream_shape() {
    let entry = entries()
        .into_iter()
        .find(|entry| entry["ieeeAddr"] == "0x00124b0000000002")
        .expect("end device fixture");
    let device = Device::from_database_entry(&entry);
    let endpoint = device.get_endpoint(1).expect("endpoint 1");
    let actual = endpoint.to_database_record();

    assert_eq!(
        actual["binds"], entry["endpoints"]["1"]["binds"],
        "endpoint binds must keep cluster/deviceIeeeAddress"
    );
    assert_eq!(
        actual["configuredReportings"], entry["endpoints"]["1"]["configuredReportings"],
        "reportings must omit an absent manufacturerCode and print integral repChange as an integer"
    );
}

#[test]
fn coordinator_power_source_is_omitted() {
    let coordinator = entries()
        .into_iter()
        .find(|entry| entry["type"] == "Coordinator")
        .expect("coordinator fixture");
    let device = Device::from_database_entry(&coordinator);
    let actual = device.test_database_entry();
    assert!(
        actual.get("powerSource").is_none(),
        "upstream getter returns undefined for power source code 0: {actual}"
    );
}

#[test]
fn group_entries_roundtrip_through_the_model() {
    Device::reset_cache();
    Group::reset_cache();
    inject_database(Arc::new(Mutex::new(Database::open(fixture()))));
    // Group members are resolved through the device registry, which loads the
    // injected database on first lookup.
    Device::by_ieee_addr("0x00124b0000000002", false).expect("fixture device");

    let group_entry = entries()
        .into_iter()
        .find(|entry| entry["type"] == "Group")
        .expect("group fixture");
    let group = Group::test_from_database_entry(&group_entry);
    assert_eq!(group.test_database_record(), group_entry);
}

#[test]
#[ignore = "set Z2M_NODE_DB to a database.db written by upstream Node"]
fn real_node_database_roundtrips() {
    let path = std::env::var("Z2M_NODE_DB").expect("Z2M_NODE_DB");
    Device::reset_cache();
    Group::reset_cache();

    for line in std::fs::read_to_string(&path).unwrap().split('\n') {
        if line.is_empty() {
            continue;
        }
        let entry: Value = serde_json::from_str(line).unwrap();
        if entry.get("type").and_then(Value::as_str) == Some("Group") {
            continue;
        }
        let device = Device::from_database_entry(&entry);
        let actual = device.test_database_entry();
        assert_eq!(
            actual, entry,
            "real device {} ({}) differs",
            entry["ieeeAddr"], entry["id"]
        );
        assert_eq!(
            serde_json::to_string(&actual).unwrap(),
            line,
            "real device {} ({}) differs at the byte level",
            entry["ieeeAddr"],
            entry["id"]
        );
    }
}

#[test]
fn integral_f64_values_are_written_like_javascript() {
    let dir = temp_dir("numbers");
    let path = dir.join("database.db");
    let mut database = Database::open(&path);
    database
        .insert(json!({
            "id": 1,
            "type": "Group",
            "groupID": 1,
            "members": [],
            "meta": {},
            "repChange": 0.0,
            "half": 0.5,
            "whole": 2.0,
        }))
        .unwrap();

    let line = std::fs::read_to_string(&path).unwrap();
    assert!(line.contains("\"repChange\":0,"), "{line}");
    assert!(line.contains("\"half\":0.5,"), "{line}");
    assert!(line.contains("\"whole\":2"), "{line}");
    assert!(!line.contains("0.0"), "{line}");
    assert!(!line.contains("2.0"), "{line}");
    let _ = std::fs::remove_dir_all(dir);
}

#[test]
#[ignore = "set Z2M_NODE_DB to a database.db written by upstream Node"]
fn real_node_database_rewritten_by_the_model_is_byte_identical() {
    use zigbee_apiarist::controller::model::entity::Entity;

    let source = std::env::var("Z2M_NODE_DB").expect("Z2M_NODE_DB");
    let dir = temp_dir("real-model");
    let path = dir.join("database.db");
    std::fs::copy(&source, &path).unwrap();

    Device::reset_cache();
    Group::reset_cache();
    inject_database(Arc::new(Mutex::new(Database::open(&path))));

    for line in std::fs::read_to_string(&source).unwrap().split('\n') {
        if line.is_empty() {
            continue;
        }
        let entry: Value = serde_json::from_str(line).unwrap();
        if entry.get("type").and_then(Value::as_str) == Some("Group") {
            continue;
        }
        Device::from_database_entry(&entry).save(false);
    }
    Entity::database().lock().unwrap().write().unwrap();

    assert_eq!(
        std::fs::read(&path).unwrap(),
        std::fs::read(&source).unwrap(),
        "model save must reproduce the Node database byte-for-byte"
    );
    let _ = std::fs::remove_dir_all(dir);
}
